//! C interface to the Asterope star tracker.
//!
//! One opaque `AsteropeTracker` is created from a camera, a `.astc` catalog
//! and a `.asti` pair index, and is then fed frames. Every function returns a
//! `AsteropeStatus`; nothing unwinds across the boundary. The header is
//! `include/asterope.h`, generated by `cbindgen`.

#![deny(unsafe_op_in_unsafe_fn)]

use core::ffi::c_char;
use core::{ptr, slice};

use asterope_core::camera::{Camera, Distortion};
use asterope_core::filter::GyroNoise;
use asterope_core::flight::{Fix, GyroAiding, StarTracker};
use asterope_core::lis::StarMatch;
use asterope_core::math::{Vec3, ARCSEC, DEG};
use asterope_core::track::TrackEvent;
use asterope_core::AsteropeError;

#[repr(C)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum AsteropeStatus {
    Ok = 0,
    /// A required pointer argument was null.
    NullPointer = 1,
    InvalidCamera = 2,
    /// The catalog bytes are truncated, damaged or of another version.
    InvalidCatalog = 3,
    /// The index bytes are truncated, damaged or of another version.
    InvalidIndex = 4,
    /// The index was not built from the catalog it was paired with.
    IndexCatalogMismatch = 5,
    /// The pixel count does not match the camera.
    InvalidFrame = 6,
    InvalidParameter = 7,
}

impl From<AsteropeError> for AsteropeStatus {
    fn from(error: AsteropeError) -> AsteropeStatus {
        match error {
            AsteropeError::InvalidCamera => AsteropeStatus::InvalidCamera,
            AsteropeError::CatalogTruncated
            | AsteropeError::CatalogBadMagic
            | AsteropeError::CatalogUnsupportedVersion
            | AsteropeError::CatalogChecksumMismatch => AsteropeStatus::InvalidCatalog,
            AsteropeError::IndexTruncated
            | AsteropeError::IndexBadMagic
            | AsteropeError::IndexUnsupportedVersion
            | AsteropeError::IndexChecksumMismatch
            | AsteropeError::IndexCorrupt
            | AsteropeError::IndexTooLarge => AsteropeStatus::InvalidIndex,
            AsteropeError::IndexCatalogMismatch => AsteropeStatus::IndexCatalogMismatch,
            AsteropeError::InvalidFrame => AsteropeStatus::InvalidFrame,
            AsteropeError::InvalidParameter
            | AsteropeError::TooFewObservations
            | AsteropeError::DegenerateGeometry => AsteropeStatus::InvalidParameter,
        }
    }
}

/// Pinhole or equidistant camera with Brown-Conrady distortion. The
/// principal point is the frame center and pixels are square.
#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct AsteropeCamera {
    pub width: u32,
    pub height: u32,
    /// Horizontal field of view, degrees.
    pub fov_x_deg: f64,
    pub k1: f64,
    pub k2: f64,
    pub k3: f64,
    pub p1: f64,
    pub p2: f64,
    /// Nonzero for an equidistant lens (distance from the principal point
    /// follows the angle from the axis instead of its tangent), as wide
    /// lenses are; zero for a pinhole.
    pub equidistant: u32,
}

#[repr(C)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum AsteropeEvent {
    /// Solved by a lost-in-space search.
    Acquired = 0,
    /// Solved from the predicted attitude.
    Tracked = 1,
    /// No solution this frame; the prediction is carried forward.
    Coasting = 2,
    /// No solution and no usable prediction.
    Lost = 3,
}

/// Result of one frame. Attitude fields are meaningful only when `solved`
/// is nonzero.
#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct AsteropeFix {
    pub event: AsteropeEvent,
    pub solved: u32,
    /// Attitude quaternion, ICRS to sensor, scalar last, `q[3] >= 0`.
    pub q: [f64; 4],
    /// Boresight right ascension and declination, degrees (ICRS).
    pub ra_deg: f64,
    pub dec_deg: f64,
    /// Position angle of image-up, north through east, degrees.
    pub roll_deg: f64,
    /// RMS angle between matched stars and their catalog positions, arcseconds.
    pub rms_arcsec: f64,
    /// One-sigma attitude uncertainty about the sensor x, y and boresight
    /// axes, arcseconds; negative when it could not be estimated.
    pub sigma_arcsec: [f64; 3],
    /// Bound on the probability that the match is a coincidence.
    pub chance_probability: f64,
    /// Estimated body rate about the sensor axes, degrees per second.
    pub body_rate_deg_s: [f64; 3],
    pub matches: u32,
    pub detections: u32,
}

/// One identified star of the latest fix.
#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct AsteropeMatch {
    /// Rank of the detection in the frame, brightest first.
    pub detection: u32,
    /// Hipparcos number, or a packed Tycho-2 designation when the top bit
    /// is set (`docs/catalog-format.md`).
    pub hip: u32,
    pub magnitude: f64,
    pub residual_arcsec: f64,
}

pub struct AsteropeTracker {
    inner: StarTracker<'static>,
    matches: Vec<StarMatch>,
}

fn fill(fix: &Fix) -> AsteropeFix {
    let event = match fix.event {
        TrackEvent::Acquired => AsteropeEvent::Acquired,
        TrackEvent::Tracked => AsteropeEvent::Tracked,
        TrackEvent::Coasting => AsteropeEvent::Coasting,
        TrackEvent::Lost => AsteropeEvent::Lost,
    };
    let rate = fix.body_rate.scale(1.0 / DEG);
    let mut out = AsteropeFix {
        event,
        solved: 0,
        q: [0.0, 0.0, 0.0, 1.0],
        ra_deg: 0.0,
        dec_deg: 0.0,
        roll_deg: 0.0,
        rms_arcsec: 0.0,
        sigma_arcsec: [-1.0; 3],
        chance_probability: 1.0,
        body_rate_deg_s: [rate.x, rate.y, rate.z],
        matches: 0,
        detections: u32::try_from(fix.detections).unwrap_or(u32::MAX),
    };
    if let Some(solution) = &fix.solution {
        out.solved = 1;
        out.q = [solution.q.x, solution.q.y, solution.q.z, solution.q.w];
        out.ra_deg = solution.pointing.ra / DEG;
        out.dec_deg = solution.pointing.dec / DEG;
        out.roll_deg = solution.pointing.roll / DEG;
        out.rms_arcsec = solution.rms_arcsec;
        if let Some(sigma) = solution.sigma {
            out.sigma_arcsec = [
                sigma.about_x / ARCSEC,
                sigma.about_y / ARCSEC,
                sigma.about_boresight / ARCSEC,
            ];
        }
        out.chance_probability = solution.chance_probability;
        out.matches = u32::try_from(solution.matches.len()).unwrap_or(u32::MAX);
    }
    out
}

/// Creates a tracker.
///
/// The catalog is decoded into memory and may be released afterwards. The
/// index is used in place.
///
/// # Safety
///
/// `camera` and `out` must be valid pointers, `catalog` and `index` must
/// point to `catalog_len` and `index_len` readable bytes, and the index
/// bytes must stay valid and unchanged until `asterope_tracker_free`.
#[no_mangle]
pub unsafe extern "C" fn asterope_tracker_new(
    camera: *const AsteropeCamera,
    catalog: *const u8,
    catalog_len: usize,
    index: *const u8,
    index_len: usize,
    out: *mut *mut AsteropeTracker,
) -> AsteropeStatus {
    if camera.is_null() || catalog.is_null() || index.is_null() || out.is_null() {
        return AsteropeStatus::NullPointer;
    }
    // SAFETY: the caller guarantees the pointers and lengths, and that the
    // index outlives the tracker, which is the only holder of this borrow.
    let (spec, catalog, index): (AsteropeCamera, &[u8], &'static [u8]) = unsafe {
        (
            *camera,
            slice::from_raw_parts(catalog, catalog_len),
            slice::from_raw_parts(index, index_len),
        )
    };
    let lens = if spec.equidistant != 0 {
        Camera::from_fov_equidistant(spec.width, spec.height, spec.fov_x_deg * DEG)
    } else {
        Camera::from_fov(spec.width, spec.height, spec.fov_x_deg * DEG)
    };
    let built = lens
        .map(|c| {
            c.with_distortion(Distortion {
                k1: spec.k1,
                k2: spec.k2,
                k3: spec.k3,
                p1: spec.p1,
                p2: spec.p2,
            })
        })
        .and_then(|camera| StarTracker::from_bytes(camera, catalog, index));
    match built {
        Ok(inner) => {
            let tracker = Box::new(AsteropeTracker {
                inner,
                matches: Vec::new(),
            });
            // SAFETY: `out` was checked for null and is valid per the contract.
            unsafe { *out = Box::into_raw(tracker) };
            AsteropeStatus::Ok
        }
        Err(error) => {
            // SAFETY: as above.
            unsafe { *out = ptr::null_mut() };
            error.into()
        }
    }
}

/// Releases a tracker. A null pointer is ignored.
///
/// # Safety
///
/// `tracker` must come from `asterope_tracker_new` and must not be used again.
#[no_mangle]
pub unsafe extern "C" fn asterope_tracker_free(tracker: *mut AsteropeTracker) {
    if !tracker.is_null() {
        // SAFETY: the pointer came from `Box::into_raw` and is released once.
        drop(unsafe { Box::from_raw(tracker) });
    }
}

unsafe fn run(
    tracker: *mut AsteropeTracker,
    pixels: *const u16,
    pixel_count: usize,
    out: *mut AsteropeFix,
    solve: impl FnOnce(&mut StarTracker<'static>, &[u16]) -> Result<Fix, AsteropeError>,
) -> AsteropeStatus {
    if tracker.is_null() || pixels.is_null() || out.is_null() {
        return AsteropeStatus::NullPointer;
    }
    // SAFETY: the caller guarantees a live tracker that no other call is
    // using, and `pixel_count` readable pixels.
    let (tracker, pixels) = unsafe { (&mut *tracker, slice::from_raw_parts(pixels, pixel_count)) };
    match solve(&mut tracker.inner, pixels) {
        Ok(fix) => {
            // SAFETY: `out` was checked for null and is valid per the contract.
            unsafe { *out = fill(&fix) };
            tracker.matches = fix.solution.map(|s| s.matches).unwrap_or_default();
            AsteropeStatus::Ok
        }
        Err(error) => error.into(),
    }
}

/// Processes the frame taken `dt` seconds after the previous one: solved
/// from the predicted attitude when one is known, by a lost-in-space search
/// otherwise. `pixels` is row-major with the top row first.
///
/// # Safety
///
/// `tracker` must be live and not in use by another call, `pixels` must
/// point to `pixel_count` readable values and `out` must be valid.
#[no_mangle]
pub unsafe extern "C" fn asterope_tracker_update(
    tracker: *mut AsteropeTracker,
    pixels: *const u16,
    pixel_count: usize,
    dt: f64,
    out: *mut AsteropeFix,
) -> AsteropeStatus {
    // SAFETY: forwarded contract.
    unsafe { run(tracker, pixels, pixel_count, out, |t, p| t.update(p, dt)) }
}

/// Solves one frame on its own by a lost-in-space search, leaving the
/// tracking state untouched.
///
/// # Safety
///
/// As for `asterope_tracker_update`.
#[no_mangle]
pub unsafe extern "C" fn asterope_tracker_solve(
    tracker: *mut AsteropeTracker,
    pixels: *const u16,
    pixel_count: usize,
    out: *mut AsteropeFix,
) -> AsteropeStatus {
    // SAFETY: forwarded contract.
    unsafe { run(tracker, pixels, pixel_count, out, |t, p| t.solve(p)) }
}

/// Copies up to `capacity` identified stars of the latest fix into `out`
/// and returns how many the fix has.
///
/// # Safety
///
/// `tracker` must be live; `out` must have room for `capacity` entries or
/// be null with a capacity of zero.
#[no_mangle]
pub unsafe extern "C" fn asterope_tracker_matches(
    tracker: *const AsteropeTracker,
    out: *mut AsteropeMatch,
    capacity: usize,
) -> usize {
    if tracker.is_null() {
        return 0;
    }
    // SAFETY: the caller guarantees a live tracker.
    let matches = unsafe { &(*tracker).matches };
    if !out.is_null() {
        for (slot, m) in matches.iter().take(capacity).enumerate() {
            let entry = AsteropeMatch {
                detection: m.detection,
                hip: m.hip,
                magnitude: m.mag,
                residual_arcsec: m.residual_arcsec,
            };
            // SAFETY: `slot < capacity`, which the caller guarantees is writable.
            unsafe { out.add(slot).write(entry) };
        }
    }
    matches.len()
}

/// Forgets the tracked attitude; the next update starts with a search.
///
/// # Safety
///
/// `tracker` must be live or null.
#[no_mangle]
pub unsafe extern "C" fn asterope_tracker_reset(tracker: *mut AsteropeTracker) {
    if !tracker.is_null() {
        // SAFETY: the caller guarantees a live tracker.
        unsafe { (*tracker).inner.reset() };
    }
}

/// Corrects for stellar aberration at the observer's velocity relative to
/// the solar-system barycenter, km/s in the ICRS axes: the Earth's velocity
/// (`asterope_earth_velocity`) plus the orbital velocity. Without it, solved
/// attitudes are off by up to 25 arcseconds.
///
/// # Safety
///
/// `tracker` must be live or null, and not in use by another call.
#[no_mangle]
pub unsafe extern "C" fn asterope_tracker_set_velocity(
    tracker: *mut AsteropeTracker,
    vx_km_s: f64,
    vy_km_s: f64,
    vz_km_s: f64,
) {
    if !tracker.is_null() {
        // SAFETY: the caller guarantees a live tracker.
        unsafe {
            (*tracker)
                .inner
                .set_velocity(Vec3::new(vx_km_s, vy_km_s, vz_km_s));
        }
    }
}

/// The filtered attitude that goes with a fix from `asterope_tracker_update_aided`.
#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct AsteropeAided {
    /// 1 once a star fix has started the filter, 0 before.
    pub valid: u32,
    /// Filtered attitude quaternion, ICRS to sensor, scalar last.
    pub q: [f64; 4],
    /// One-sigma uncertainty about the sensor x, y and boresight axes, arcseconds.
    pub sigma_arcsec: [f64; 3],
    /// Estimated gyro bias about the sensor axes, degrees per second.
    pub gyro_bias_deg_s: [f64; 3],
    /// The frame's star fix weighed against the gyro's prediction; negative
    /// when the frame gave no fix. About 3 on average for fixes that belong.
    pub normalized_residual_squared: f64,
    /// 1 when the star fix was taken into the filter.
    pub fix_accepted: u32,
}

/// Turns on gyro aiding. `angle_random_walk` is in degrees per root second,
/// `rate_random_walk` in degrees per second per root second, `row_time` the
/// rolling-shutter delay between rows in seconds (zero for a global
/// shutter).
///
/// # Safety
///
/// `tracker` must be live or null, and not in use by another call.
#[no_mangle]
pub unsafe extern "C" fn asterope_tracker_enable_gyro(
    tracker: *mut AsteropeTracker,
    angle_random_walk: f64,
    rate_random_walk: f64,
    row_time: f64,
) {
    if !tracker.is_null() {
        let settings = GyroAiding {
            row_time,
            ..GyroAiding::new(GyroNoise {
                angle_random_walk: angle_random_walk * DEG,
                rate_random_walk: rate_random_walk * DEG,
            })
        };
        // SAFETY: the caller guarantees a live tracker.
        unsafe { (*tracker).inner.enable_gyro(settings) };
    }
}

/// Takes a gyro reading, degrees per second about the sensor axes, that
/// covers the `dt` seconds since the previous one.
///
/// # Safety
///
/// `tracker` must be live or null, and not in use by another call.
#[no_mangle]
pub unsafe extern "C" fn asterope_tracker_gyro(
    tracker: *mut AsteropeTracker,
    x_deg_s: f64,
    y_deg_s: f64,
    z_deg_s: f64,
    dt: f64,
) {
    if !tracker.is_null() {
        let reading = Vec3::new(x_deg_s, y_deg_s, z_deg_s).scale(DEG);
        // SAFETY: the caller guarantees a live tracker.
        unsafe { (*tracker).inner.gyro(reading, dt) };
    }
}

/// Processes a frame taken at the time of the latest gyro reading. `fix`
/// receives what the camera found and `aided` the filtered attitude, which
/// stays valid through frames without stars.
///
/// # Safety
///
/// As for `asterope_tracker_update`; `aided` must point to a writable
/// `AsteropeAided`.
#[no_mangle]
pub unsafe extern "C" fn asterope_tracker_update_aided(
    tracker: *mut AsteropeTracker,
    pixels: *const u16,
    pixel_count: usize,
    fix: *mut AsteropeFix,
    aided: *mut AsteropeAided,
) -> AsteropeStatus {
    if aided.is_null() {
        return AsteropeStatus::NullPointer;
    }
    let mut filtered = None;
    // SAFETY: forwarded contract.
    let status = unsafe {
        run(tracker, pixels, pixel_count, fix, |t, p| {
            t.update_aided(p).map(|result| {
                filtered = Some(AsteropeAided {
                    valid: u32::from(result.attitude.is_some()),
                    q: result
                        .attitude
                        .map_or([0.0, 0.0, 0.0, 1.0], |q| [q.x, q.y, q.z, q.w]),
                    sigma_arcsec: [
                        result.sigma.x / ARCSEC,
                        result.sigma.y / ARCSEC,
                        result.sigma.z / ARCSEC,
                    ],
                    gyro_bias_deg_s: [
                        result.gyro_bias.x / DEG,
                        result.gyro_bias.y / DEG,
                        result.gyro_bias.z / DEG,
                    ],
                    normalized_residual_squared: result
                        .innovation
                        .map_or(-1.0, |i| i.normalized_squared),
                    fix_accepted: u32::from(result.innovation.is_some_and(|i| i.accepted)),
                });
                result.fix
            })
        })
    };
    if let Some(filtered) = filtered {
        // SAFETY: `aided` was checked for null and is valid per the contract.
        unsafe { *aided = filtered };
    }
    status
}

/// Writes the Earth's velocity about the Sun, km/s in the ICRS axes, at a
/// Julian date in terrestrial time.
///
/// # Safety
///
/// `out` must point to three writable values or be null.
#[no_mangle]
pub unsafe extern "C" fn asterope_earth_velocity(jd_tt: f64, out: *mut f64) {
    if !out.is_null() {
        let v = asterope_core::ephem::earth_velocity_km_s(jd_tt);
        // SAFETY: the caller guarantees three writable values.
        unsafe { out.cast::<[f64; 3]>().write([v.x, v.y, v.z]) };
    }
}

/// A static, null-terminated description of a status code.
#[no_mangle]
pub extern "C" fn asterope_status_message(status: AsteropeStatus) -> *const c_char {
    let text: &'static core::ffi::CStr = match status {
        AsteropeStatus::Ok => c"ok",
        AsteropeStatus::NullPointer => c"a required pointer is null",
        AsteropeStatus::InvalidCamera => c"camera parameters are invalid",
        AsteropeStatus::InvalidCatalog => c"catalog data is damaged or unsupported",
        AsteropeStatus::InvalidIndex => c"index data is damaged or unsupported",
        AsteropeStatus::IndexCatalogMismatch => c"index was not built from this catalog",
        AsteropeStatus::InvalidFrame => c"pixel count does not match the camera",
        AsteropeStatus::InvalidParameter => c"parameter is out of range",
    };
    text.as_ptr()
}
